--- a/11-zoomable-treemap.html
+++ b/11-zoomable-treemap.html
@@ -148,11 +148,9 @@
 const cellFill = (d) => {
   let n = d; while (n.depth > 1) n = n.parent;
   const base = d3.hcl(color(n.data.name));
-  if (d.depth === 1) { base.l = 45; base.c *= 0.9; return base.toString(); }
-  if (d.depth === 2) { base.l = 60; base.c *= 0.7; return base.toString(); }
-  // leaf
-  base.l = 72 + rng() * 10;
-  base.c *= 0.5;
+  if (d.depth === 1) { base.l = 45; base.c *= 0.9; }
+  else if (d.depth === 2) { base.l = 60; base.c *= 0.7; }
+  else { base.l = 72 + rng() * 10; base.c *= 0.5; }
   return base.toString();
 };

@@ -197,10 +195,8 @@
 let currentFocus = root;

 // ── Render ──
-const allNodes = root.descendants().filter(d => d.depth > 0);
-
 const cell = container.selectAll("g")
-  .data(allNodes, d => d.data.name + d.depth + (d.parent ? d.parent.data.name : ""))
+  .data(root.descendants().slice(1), d => d.data.name + d.depth + (d.parent ? d.parent.data.name : ""))
   .join("g")
     .attr("transform", d => `translate(${x(d.x0)},${y(d.y0)})`);

@@ -245,15 +241,8 @@
     }
     el.style("pointer-events", vis ? "auto" : "none");

-    // Label fitting
-    el.select(".group-label")
-      .attr("opacity", (sw > 40 && sh > 18) ? 1 : 0);
-
-    el.select(".leaf-label")
-      .attr("opacity", (sw > 30 && sh > 16) ? 1 : 0);
-
-    el.select(".leaf-size")
-      .attr("opacity", (sw > 40 && sh > 28) ? 1 : 0);
+    [[".group-label",40,18],[".leaf-label",30,16],[".leaf-size",40,28]]
+      .forEach(([c,mw,mh]) => el.select(c).attr("opacity", sw > mw && sh > mh ? 1 : 0));
   });
 };

@@ -281,10 +270,8 @@
            <div><strong>${d.data.name}</strong></div>
            <div class="size">${fmt(d.value)}${d.height > 0 ? ` (${d.leaves().length} files)` : ""}</div>`);
 })
